"""General stage-two exploration. No AI call, no live-vacancy or eligibility claims."""
from copy import deepcopy
from datetime import datetime, timezone, timedelta
from background_options import TOPICS, TASKS, PREF_SINGLE, PREF_MULTI, PREF_LABELS, CHANNELS, KEYWORDS
from background_guidance import validate_background, make_background_guidance
from personality_v12 import evaluate
from matching import build_report
from report_markdown import render_report, text
from role_exploration import explore_roles

CHANNEL_INFO={
 'internship':('https://www.undp.org/careers/frequently-asked-questions','先用实习公告了解真实任务；逐项核对在读／毕业时间、专业、语言、期限与报酬。实习不承诺后续雇佣。'),
 'staff':('https://www.undp.org/careers/frequently-asked-questions','按专业任务检索工作人员岗位，再核对经验、学历、语言、招聘范围与工作许可。不能用总工作年限直接换算职级。'),
 'consultancy':('https://www.undp.org/careers/faq','对照工作范围、交付物、时间安排与合同条件；顾问或项目合同不等同于长期工作人员岗位。'),
 'unv':('https://www.unv.org/become-volunteer/','区分具体志愿岗位类别，核对学历、经验、语言、服务地及待遇；志愿服务不等于无专业要求。'),
 'online_volunteer':('https://www.unv.org/become-online-volunteer','线上志愿任务可作为远程参与的探索入口，但不提供报酬；不等同于联合国工作人员或现场 UN Volunteer 身份。'),
 'early_career':('https://www.undp.org/jposc','JPO 等专项渠道需按当期项目核对资助方、国籍、学历、年龄和经验等条件，不能仅凭“刚毕业”判断资格。')}

def choices(value, options, label):
 if not isinstance(value,list) or any(not isinstance(v,str) or v not in options for v in value) or len(set(value))!=len(value):
  raise ValueError(label+'选项无效或重复')

def validate(profile):
 if not isinstance(profile,dict) or set(profile)-{'primary_path','topics','tasks','background','preferences'}:
  raise ValueError('背景问卷字段无效，请刷新网页后重试')
 if profile.get('primary_path') not in ('student','experienced'):raise ValueError('请选择本次主要路径')
 for key,opts in [('topics',TOPICS),('tasks',TASKS)]:choices(profile.get(key,[]),opts,key)
 validate_background(profile.get('background',{}))
 prefs=profile.get('preferences',{})
 if not isinstance(prefs,dict) or set(prefs)-set(PREF_SINGLE)-set(PREF_MULTI):raise ValueError('背景偏好字段无效')
 for key,options in PREF_SINGLE.items():
  if key in prefs and (not isinstance(prefs[key],str) or prefs[key] not in options):raise ValueError(PREF_LABELS[key]+'选项无效')
 for key,options in PREF_MULTI.items():choices(prefs.get(key,[]),options,PREF_LABELS[key])
 if 'anywhere' in prefs.get('regions',[]) and len(prefs['regions'])>1:raise ValueError('“全球均可”与具体地区请择一选择')
 bands=list(PREF_SINGLE['total_years_band'])
 if prefs.get('total_years_band') and prefs.get('relevant_years_band') and bands.index(prefs['relevant_years_band'])>bands.index(prefs['total_years_band']):raise ValueError('相关工作年限区间不能高于总工作年限区间')
 return deepcopy(profile)

def channel_cards(profile):
 p=profile.get('preferences',{});b=profile.get('background',{})
 selected=p.get('channels') or (['internship','online_volunteer','early_career'] if profile['primary_path']=='student' else ['staff','consultancy','unv'])
 cards=[]
 for key in selected:
  url,description=CHANNEL_INFO[key]
  reasons=['你主动选择了这一渠道。' if p.get('channels') else ('按你选择的学生／早期探索路径提供阅读起点。' if profile['primary_path']=='student' else '按你选择的有经验／转行路径提供阅读起点。')]
  checks=['具体开放岗位、截止时间与完整申请要求仍需查当期公告。']
  status='待逐项核对'
  if key=='online_volunteer' and b.get('requires_pay') is True:
   status='与必须有报酬的要求冲突';checks.insert(0,'仅可作为了解渠道，不列为当前有薪求职方案。')
  if p.get('availability') in ('part_time','short_term') and key in ('staff','internship','unv','early_career'):
   checks.insert(0,'你只考虑兼职／短期安排，需优先核对岗位的服务时长与每周投入，不能默认可以兼任。')
  if b.get('relocation')=='no' and key!='online_volunteer':checks.insert(0,'你不接受搬迁，仅核对本地岗位或明确允许现居地远程工作的岗位。')
  if b.get('contract')=='stable' and key in ('consultancy','online_volunteer','internship','unv'):checks.insert(0,'这一渠道不直接满足你优先稳定雇佣合同的偏好，需比较期限及身份。')
  if p.get('availability')=='explore':reasons.append('当前只做方向了解，不催促进入申请。')
  cards.append({'id':key,'title':CHANNELS[key],'status':status,'description':description,'reasons':reasons,'checks':checks,'source':{'url':url,'checked_at':'2026-10-16','scope':'渠道概览；非实时空缺或个人资格核验'}})
 return cards

def generate_report(payload,evaluator=None):
 if not isinstance(payload,dict) or set(payload)-{'answers','profile','supplement'}:raise ValueError('报告请求字段无效')
 profile=validate(payload.get('profile'));supplement=payload.get('supplement',{})
 today=datetime.now(timezone(timedelta(hours=8))).date().isoformat()
 report=build_report(payload.get('answers',{}),profile,[],supplement,as_of=today,evaluator=evaluator or evaluate)
 report['background_guidance']=make_background_guidance(profile,supplement)
 report['general_channels']=channel_cards(profile)
 report['report_mode']='rules_and_sources';report['background_version']='2.0'
 # Only show evidence cards with an actual overlap, never replace an uncovered new interest with an unrelated card.
 legacy={**profile,'topics':[x for x in profile.get('topics',[]) if x in {'international_law','sustainable_development','education_children','social_policy','humanitarian_protection','environment_climate','economic_research'}]}
 exploration=explore_roles(legacy,as_of=today)
 if exploration['mode']=='browse' and (profile.get('topics') or profile.get('tasks')):exploration['cards']=[];exploration['additional_directions']=[]
 report['role_exploration']=exploration
 prefs=profile.get('preferences',{});b=profile.get('background',{})
 summary=[]
 for key,opts in {**PREF_SINGLE,**PREF_MULTI}.items():
  val=prefs.get(key)
  if val:summary.append({'field':key,'label':PREF_LABELS[key],'value':'、'.join(opts[x] for x in val) if isinstance(val,list) else opts[val]})
 guidance=report['location_matching']['guidance']
 if prefs.get('settings'):
  guidance['title']='先按你选择的工作环境找任务'
  guidance['detail']='你选择了：'+'、'.join(PREF_MULTI['settings'][v] for v in prefs['settings'])+'。这些是探索偏好，不表示已经确定某个驻地或满足岗位要求。'
  guidance['search_suggestion']='在官方岗位检索中分别查看工作地点、办公室职能和远程安排，再对照实际职责。'
 if b.get('relocation')=='no':
  guidance['mobility']='你不接受搬迁：优先核对现居地岗位或明确允许该所在地远程工作的岗位；其他地区兴趣不能覆盖这一限制。'
 if b.get('travel')=='none':guidance['mobility']+=' 你不接受出差，须排查强制出差职责。'
 report['preference_summary']=summary
 report['search_directions']=[{'topic':TOPICS[x],'keywords':KEYWORDS[x], 'basis':'用户选择的议题；检索词为编辑建议'} for x in profile.get('topics',[])]
 intro=['## 你希望怎样参与','']
 intro += [f"- {text(x['label'])}：{text(x['value'])}" for x in summary]
 if not summary:intro+=['你尚未限定时间、地点或参与渠道，先保留开放选项。']
 if b.get('acceptable_places'):intro+=['补充地点：'+text(b['acceptable_places'])]
 intro+=['','地区、城市和办公室类型分别记录。总部不等于某个大洲，国家办公室也不自动等于高风险驻地。所选地点用于你的检索清单，尚未逐岗核对可用职位或工作许可。','']
 if b.get('relocation')=='no':intro+=['你选择了不搬迁：以现居地或允许该所在地远程工作的岗位为先；其他驻地兴趣不能覆盖这一限制。','']
 if b.get('travel')=='none':intro+=['你选择了不出差：目标公告中如有强制出差，需要作为条件冲突核对。','']
 if prefs.get('start_window'):intro+=['可开始时间用于比较岗位到岗要求；不再询问某个固定暑期项目的日期。','']
 intro+=['## 从你选择的兴趣开始检索','']
 for direction in report['search_directions']:intro += ['- '+text(direction['topic'])+'：可尝试检索 '+text(direction['keywords'])+'。']
 if profile.get('tasks'):intro+=['','你想尝试的任务：'+'、'.join(TASKS[x] for x in profile['tasks'])+'。从中选一项做工作样本，不能把勾选视为已有能力。']
 if not report['search_directions']:intro+=['暂未选择议题，可先从一项愿意尝试的日常任务开始。']
 intro+=['','这些是检索方向，不是已开放职位。扩展议题尚未全部建立机构证据卡；缺少证据时只给关键词，不补造机构匹配。','']
 if prefs.get('training') or prefs.get('deliverables') or prefs.get('experience_types') or prefs.get('total_years_band'):
  intro+=['## 把已有背景变成准备材料','','从你选择的训练、经历和成果中选一个样本，写清本人责任、方法、交付物与结果。课程和志愿项目不自动折算为正式工作年限；区间自报不用于确定职级。','']
 guide=report['background_guidance']
 if prefs.get('training'):guide['questions_to_check']=[x for x in guide['questions_to_check'] if not x.startswith('补充专业')]
 if prefs.get('experience_types') or prefs.get('deliverables') or prefs.get('total_years_band'):guide['questions_to_check']=[x for x in guide['questions_to_check'] if not x.startswith('提供一项')]
 if prefs.get('regions') or prefs.get('cities') or prefs.get('settings'):guide['questions_to_check']=[x for x in guide['questions_to_check'] if not x.startswith('明确可接受地点')]
 for item in guide['items']:
  if item['id']=='experience_evidence':
   if prefs.get('total_years_band'):item['detail']=item['detail'].replace('总工作年限未提供。','自报总工作年限区间为'+PREF_SINGLE['total_years_band'][prefs['total_years_band']]+'。')
   if prefs.get('relevant_years_band'):item['detail']=item['detail'].replace('相关年限未知，不从总年限推算。','自报相关工作年限区间为'+PREF_SINGLE['relevant_years_band'][prefs['relevant_years_band']]+'，具体岗位仍需逐段核对。')
   for key in ['total_years_band','relevant_years_band']:
    if prefs.get(key):item['evidence'].append({'profile_field':'preferences.'+key,'label':PREF_LABELS[key],'value':PREF_SINGLE[key][prefs[key]]})
 md=render_report(report,[])
 channels=['## 可以继续了解的渠道','', '依据你的路径、主动选择和现实限制列出，顺序不代表录用概率。','']
 for c in report['general_channels']:
  channels+=['### '+c['title'],'',c['status'],'',c['description'],'','为什么展示：'+' '.join(c['reasons']),'']+['- '+x for x in c['checks']]+['',f"[官方来源]({c['source']['url']})；核查日 {c['source']['checked_at']}。",'']
 start=md.index('## 具体渠道与你的现实条件');end=md.index('## 下一步可以做什么',start)
 md=md[:start]+'\n'.join(channels)+'\n'+md[end:]
 md=md.replace('## 结合你的背景：准备与现实条件','\n'.join(intro)+'\n## 结合你的背景：准备与现实条件',1) if '## 结合你的背景：准备与现实条件' in md else md+'\n'+'\n'.join(intro)
 md=md.replace('探索资料正在等待复核；可以先做画像中的体验任务。','已选方向暂无对应的已核对机构卡；请使用上方检索词继续查找官方资料。')
 md=md.replace('评分版本：未提供', '评分版本：'+report['result_version'])
 today=datetime.now(timezone(timedelta(hours=8))).date().isoformat()
 scope={'title':'全球职业方向与渠道探索','candidate_count':len(report['general_channels']),'complete_international_organization_coverage':False,'notice':'本报告由规则与资料生成，不是实时岗位清单，也不确认申请资格。'}
 report['generated_on']=today
 return {'report':report,'markdown':md,'scope':scope,'input':deepcopy(payload),'sources':[c['source'] for c in report['general_channels']]}

