"""Optional self-reported background -> traceable preparation advice, never eligibility."""
from copy import deepcopy
import re

ENUMS = {
    'degree': {'secondary':'高中及以下', 'bachelor':'本科', 'master':'硕士', 'doctorate':'博士', 'other':'其他学历'},
    'degree_status': {'studying':'在读', 'completed':'已完成'},
    'study_field': {'law':'法律', 'finance':'金融／经济', 'policy':'公共政策／社会科学', 'environment':'环境／气候', 'education':'教育', 'communications':'传播／语言', 'technology':'技术／数据', 'other':'其他／跨学科'},
    'relocation': {'no':'暂不接受搬迁', 'conditional':'条件合适可以搬迁', 'yes':'可以搬迁'},
    'travel': {'none':'不接受出差', 'occasional':'可以偶尔短期出差', 'frequent':'可以较频繁出差'},
    'contract': {'stable':'优先较稳定的雇佣合同', 'fixed_term':'可接受定期雇佣合同', 'consultancy':'可接受咨询／项目合同', 'flexible':'合同形式可比较'},
    'funding': {'need_support':'需要覆盖参与或迁居成本的支持', 'budget_first':'希望先核算成本', 'self_funded':'可以考虑自筹费用'},
}
ENUMS['study_field'].update({'health':'医学／公共卫生','agriculture':'农业／食品科学','engineering':'工程／基础设施','social_work':'社会工作／心理学','business':'管理／人力资源／物流','culture':'文化／历史／艺术'})
STRINGS = {'major':120, 'courses':400, 'experience_summary':600, 'work_sample':600, 'current_city':80, 'acceptable_places':200}
NUMBERS = {'total_years', 'relevant_years'}
LANGUAGE_TASKS = {'reading':'阅读专业材料', 'writing':'撰写工作材料', 'discussion':'参加工作讨论', 'presentation':'作口头汇报'}
FIELDS = set(ENUMS) | set(STRINGS) | NUMBERS | {'languages', 'requires_pay', 'degree_month'}
LABELS = {'degree_month':'该学历预计或实际毕业年月', 'degree':'学历', 'degree_status':'学历状态', 'study_field':'学习领域', 'major':'专业', 'courses':'课程／训练',
          'experience_summary':'相关经历', 'work_sample':'可展示成果', 'current_city':'当前生活基地', 'acceptable_places':'可接受地点',
          'total_years':'总工作年限', 'relevant_years':'自报相关年限', 'languages':'语言实际使用', 'requires_pay':'是否必须有报酬',
