def validate_background(value):
    if not isinstance(value, dict) or set(value) - FIELDS:
        raise ValueError('补充背景字段无效')
    month=value.get('degree_month')
    if month is not None and (not isinstance(month,str) or not re.fullmatch(r'[1-9][0-9]{3}-(0[1-9]|1[0-2])',month)):
        raise ValueError('学历毕业年月须为 YYYY-MM；未知请留空')
    for field, options in ENUMS.items():
        if value.get(field) is not None and (not isinstance(value[field], str) or value[field] not in options):
            raise ValueError(LABELS[field] + '选项无效')
    for field, limit in STRINGS.items():
        v = value.get(field)
        if v is not None and (not isinstance(v, str) or len(v) > limit or any(ord(c)<32 and c not in '\n\t' for c in v)):
            raise ValueError(LABELS[field] + '格式或长度无效')
    for field in NUMBERS:
        v = value.get(field)
        if v is not None and (type(v) not in (int, float) or not 0 <= v <= 70):
            raise ValueError(LABELS[field] + '须为 0—70 的数字；未知请留空')
    if value.get('relevant_years') is not None and value.get('total_years') is not None and value['relevant_years'] > value['total_years']:
        raise ValueError('相关工作年限不能大于总工作年限；课程和志愿项目可另写在经历中')
    if value.get('requires_pay') is not None and type(value['requires_pay']) is not bool:
        raise ValueError('报酬要求只接受是、否或未知')
    languages = value.get('languages', [])
    if not isinstance(languages, list) or len(languages)>5:
        raise ValueError('语言最多填写五项')
    seen=set()
    for item in languages:
        if not isinstance(item,dict) or set(item)-{'name','tasks','evidence'}:
            raise ValueError('语言信息字段无效')
        name=item.get('name')
        if not isinstance(name,str) or not name.strip() or len(name)>40 or name.strip().casefold() in seen:
            raise ValueError('语言名称须为非空、不重复的文本，最多 40 字')
        seen.add(name.strip().casefold())
        tasks=item.get('tasks',[])
        if not isinstance(tasks,list) or any(not isinstance(t,str) or t not in LANGUAGE_TASKS for t in tasks) or len(set(tasks))!=len(tasks):
            raise ValueError('语言使用任务无效')
        evidence=item.get('evidence','')
        if not isinstance(evidence,str) or len(evidence)>300:
            raise ValueError('语言使用例子最多 300 字')
    return deepcopy(value)


