    else:missing.append('说明一种语言能用于哪些工作任务；未填写不代表没有语言能力。')
    if b.get('experience_summary') or b.get('work_sample') or b.get('total_years') is not None or b.get('relevant_years') is not None:
        years='你自报总工作年限为'+str(b['total_years'])+'年。' if b.get('total_years') is not None else '总工作年限未提供。'
        years+=('自报相关年限为'+str(b['relevant_years'])+'年，仍须按具体岗位职责逐段核实。') if b.get('relevant_years') is not None else '相关年限未知，不从总年限推算。'
        detail=('课程、校园或志愿项目也可以帮助体验任务；它们不自动算正式工作年限。' if profile['primary_path']=='student' else '先比较能够迁移的任务、责任和成果，不默认需要从实习开始。')
        detail+=years+('从你填写的成果中选一项，标注目标、本人贡献、方法与结果，对照目标岗位的一条职责。' if b.get('work_sample') else '先整理一项可以描述的交付物；没有可分享文件时可写匿名摘要。')
        add('experience_evidence','把经历拆成职责与成果',detail,['experience_summary','work_sample','total_years','relevant_years'])
    else:missing.append('提供一项课程、志愿或工作成果；转行者可优先写已有专长，不必先寻找实习。')
    if any(b.get(f) for f in ['current_city','acceptable_places','relocation','travel']):
        detail='以你明确填写的地点和流动限制为准；以下探索方向不表示你必须迁居或接受出差。'
        if b.get('relocation')=='no':detail+='你暂不接受搬迁，先核对当地或允许现居地远程工作的岗位；“远程”仍须核对工作许可和允许所在地。'
        if b.get('travel')=='none':detail+='你不接受出差，核对是否有强制出差职责。'
        if b.get('travel')=='none' and (supplement.get('L04') or 0)>=4:detail+='补充题表达过出差兴趣，但兴趣不覆盖这里的明确限制。'
        detail+='当前岗位库尚未逐项核实这些安排，未知项保留为待核对，不标为已满足。'
        add('mobility_limits','先确认能接受的工作安排',detail,['current_city','acceptable_places','relocation','travel'])
    else:missing.append('明确可接受地点、搬迁和出差限制；未填写时保持待核对。')
    if b.get('requires_pay') is not None or b.get('contract') or b.get('funding'):
        detail='合同名称、时长、福利与报酬需要分别核对。'
        if b.get('requires_pay') is True:detail+='你明确要求有报酬；已接入渠道按其薪酬资料单独比较，未知薪酬不能算可行。'
        elif b.get('requires_pay') is False:detail+='你没有设置必须有报酬的限制，这不代表你愿意接受任何无薪安排。'
        if b.get('funding')=='need_support':detail+='即使岗位有报酬，也须确认到账时间以及差旅、签证、住宿和保险是否需要垫付；有薪不等于成本已覆盖。'
        elif b.get('funding'):detail+='用实际薪酬、生活成本、迁居支出和到账时间做一次预算，不必提供个人资产。'
        if b.get('contract')=='stable':detail+='优先稳定合同的偏好不能由机构名称保证；要逐份核对合同期限和续约条件。'
        add('financial_limits','先核对合同与参与成本',detail,['requires_pay','contract','funding'])
    else:missing.append('说明报酬、合同或参与成本的底线，避免把有兴趣误写成现实可行。')
    return {'version':'0.1','notice':'以下依据你自报的背景提供准备建议；没有核验学历、语言或经历，不新增资格认定。',
            'items':items,'questions_to_check':missing}


