"""岗位级规则试测：外部事实须经编辑核查；无录取预测、无在线职位发现。"""
from datetime import date
import re

VERSION = 'matching-0.2-pilot'
VALID_STATES = {'met', 'not_met', 'unknown', 'not_applicable'}


def calendar_month(value):
    """只接受明确的 YYYY-MM；空缺、错格式和不可能月份均不推断。"""
    if not isinstance(value, str) or not re.fullmatch(r'[0-9]{4}-[0-9]{2}', value):
        return None
    try:
        return date.fromisoformat(value + '-01')
    except ValueError:
        return None


def evidence_valid(evidence, as_of):
    """只检查编辑提供的证据状态与有效期，不声称自动验证网页内容。"""
    if not isinstance(evidence, dict):
        return False
    try:
        return (evidence.get('status') == 'verified'
                and evidence.get('url', '').startswith('https://')
                and date.fromisoformat(evidence['checked_at']) <= as_of
                <= date.fromisoformat(evidence['review_by']))
    except (KeyError, TypeError, ValueError):
        return False


def assess_condition(condition, profile, sources, as_of):
    """条件只在本候选内生效。模糊或含例外规则应由编辑标为 manual。"""
    key = condition['field']
    value = profile.get(key)
    ref = condition.get('source_id')
    result = {'field': key, 'user_value': value, 'source_id': ref,
              'status': 'unknown', 'reason': '资料缺失、过期或条件需要人工解释'}
    if not evidence_valid(sources.get(ref), as_of):
        return result
    op = condition.get('op')
    expected = condition.get('value')
    if op == 'not_applicable':
        result.update(status='not_applicable', reason='来源明确说明该条件不适用')
        return result
    if value is None or op == 'manual':
        return result
    if op == 'in' and isinstance(value, str) and isinstance(expected, list):
        passed = value in expected
    elif op == 'gte' and type(value) in (int, float) and type(expected) in (int, float):
        passed = value >= expected
    elif op == 'eq' and type(value) is type(expected):
        passed = value == expected
    elif op == 'month_between' and isinstance(expected, list) and len(expected) == 2:
        actual = calendar_month(value)
        lower, upper = (calendar_month(v) for v in expected)
        if actual is None or lower is None or upper is None or lower > upper:
            return result
        passed = lower <= actual <= upper
    else:
        return result
    result.update(status='met' if passed else 'not_met',
                  reason='按该渠道已核对的条件比较', expected=expected, operator=op)
    return result


def location_preferences(answers):
    allowed = {f'L{i:02}' for i in range(1, 7)} | {'S01', 'S02', 'W01', 'W02'}
    if not isinstance(answers, dict) or set(answers) - allowed:
        raise ValueError('补充量表题号无效')
    if any(v is not None and (type(v) is not int or not 1 <= v <= 5)
           for v in answers.values()):
        raise ValueError('补充量表只接受 1—5 整数或 null')
    high = lambda q: answers.get(q) is not None and answers[q] >= 4
    signals = []
    if high('L01') and high('L02'):
        signals.append({'signal': 'connect_practice_and_methods', 'answers': ['L01', 'L02']})
    else:
        for q, signal in [('L01', 'follow_local_implementation'), ('L02', 'cross_office_methods')]:
            if high(q):
                signals.append({'signal': signal, 'answers': [q]})
    if high('L03') and high('L04'):
        signals.append({'signal': 'fixed_base_with_travel', 'answers': ['L03', 'L04']})
    else:
        for q, signal in [('L03', 'stable_base'), ('L04', 'travel_interest')]:
            if high(q):
                signals.append({'signal': signal, 'answers': [q]})
    for q, signal in [('L05', 'partner_contact'), ('L06', 'analysis_and_writing')]:
        if high(q):
            signals.append({'signal': signal, 'answers': [q]})
    from workplace_guidance import workplace_guidance
    return {'status': 'preference_signals_only', 'signals': signals,
            'guidance': workplace_guidance(answers),
            'answers': answers, 'office_assignment': None,
            'limits': '未测量风险承受能力；需按岗位地点和用户明确限制另行核对。'}


def workplace_facts(candidate, as_of):
    """各项只能来自该渠道证据；城市、办公室职能与流动安排不互相推断。"""
    arrangements = candidate.get('arrangements', {})
    sources = candidate.get('sources', {})
    result = {}
    for field in ('city', 'office_scope', 'work_mode', 'travel_pattern', 'field_setting'):
        fact = arrangements.get(field, {})
        ref = fact.get('source_id')
        value = fact.get('value')
        supported = (isinstance(value, str) and bool(value.strip())
                     and evidence_valid(sources.get(ref), as_of))
        if field == 'office_scope' and value not in {'headquarters', 'regional', 'country', 'project'}:
            supported = False
        result[field] = {'status': 'supported' if supported else 'unknown',
                         'value': value if supported else None, 'source_id': ref}
    return result


def match_candidate(candidate, profile, as_of):
    sources = candidate.get('sources', {})
    conditions = [assess_condition(c, profile, sources, as_of)
                  for c in candidate.get('requirements', [])]
    # completeness 来源与各条件来源必须分别有效，防止空条件表默认通过。
    complete = (candidate.get('requirements_complete') is True
                and evidence_valid(sources.get(candidate.get('requirements_source_id')), as_of)
                and bool(conditions))
    if any(c['status'] == 'not_met' for c in conditions):
        eligibility = 'not_met'
    elif complete and all(c['status'] in {'met', 'not_applicable'} for c in conditions):
        eligibility = 'checked_requirements_met'
    else:
        eligibility = 'unknown'

    constraints = []
    for field, accepted in profile.get('constraints', {}).items():
        if not isinstance(accepted, list) or not accepted:
            raise ValueError('明确限制必须是非空的可接受值列表')
        fact = candidate.get('arrangements', {}).get(field, {})
        supported = evidence_valid(sources.get(fact.get('source_id')), as_of)
        value = fact.get('value')
        status = ('unknown' if not supported or value is None else
                  'met' if value in accepted else 'not_met')
        constraints.append({'field': field, 'accepted': accepted, 'role_value': value,
                            'source_id': fact.get('source_id'), 'status': status})

    fit = {}
    for field in ('topics', 'tasks', 'experience'):
        user_values = profile.get(field)
        fact = candidate.get('fit', {}).get(field, {})
        values = fact.get('values')
        valid = (isinstance(user_values, list) and bool(user_values)
                 and isinstance(values, list) and bool(values)
                 and evidence_valid(sources.get(fact.get('source_id')), as_of))
        overlaps = sorted(set(user_values) & set(values)) if valid else []
        # 没有标签重合也可能只是词表不全，不作为不适合的证明。
        fit[field] = {'status': 'supported' if overlaps else 'unknown',
                      'overlap': overlaps, 'source_id': fact.get('source_id')}

    task_evidence = candidate.get('fit', {}).get('tasks', {})
    has_tasks = (bool(task_evidence.get('values'))
                 and evidence_valid(sources.get(task_evidence.get('source_id')), as_of))
    if eligibility == 'not_met' or any(c['status'] == 'not_met' for c in constraints):
        bucket = 'not_currently_actionable'
    elif not has_tasks:
        bucket = 'research_lead'
    elif eligibility == 'unknown' or any(c['status'] == 'unknown' for c in constraints):
        bucket = 'verify_before_comparing'
    else:
        bucket = 'conditions_checked'

    vacancy = candidate.get('vacancy', {})
    try:
        live = (candidate.get('record_kind') == 'vacancy'
                and evidence_valid(sources.get(vacancy.get('source_id')), as_of)
                and date.fromisoformat(vacancy['opens_on']) <= as_of
                <= date.fromisoformat(vacancy['closes_on']))
    except (KeyError, TypeError, ValueError):
        live = False
    return {'id': candidate['id'], 'title': candidate['title'],
            'record_kind': candidate['record_kind'], 'bucket': bucket,
            'eligibility': eligibility, 'conditions': conditions,
            'constraints': constraints, 'fit': fit,
            'workplace': workplace_facts(candidate, as_of),
            'published_opening_in_date_range': live,
            'application_status': ('check_live_announcement' if live and bucket == 'conditions_checked'
                                   else 'not_established'),
            'limits': '规则依据自报背景及编辑资料；不代表竞争力、录取机会或名额可用。'}


def match_all(candidates, profile, supplement=None, as_of=None):
    """暂不在同组内打分排序：未知项不能按零分计算；顺序仅为资料顺序。"""
    as_of = date.fromisoformat(as_of) if as_of else date.today()
    ids = [c['id'] for c in candidates]
    if len(ids) != len(set(ids)):
        raise ValueError('候选 ID 不得重复')
    groups = {key: [] for key in ['conditions_checked', 'verify_before_comparing',
                                 'research_lead', 'not_currently_actionable']}
    for candidate in candidates:
        result = match_candidate(candidate, profile, as_of)
        groups[result['bucket']].append(result)
    return {'version': VERSION, 'as_of': as_of.isoformat(), 'groups': groups,
            'location': location_preferences(supplement or {}),
            'ranking': 'not_ranked_within_groups', 'production_ready': False}


def build_report(core_answers, profile, candidates, supplement=None, as_of=None, evaluator=None):
    from scoring import evaluate
    from action_plan import make_action_plan
    report = (evaluator or evaluate)(core_answers)
    matching = match_all(candidates, profile, supplement, as_of)
    report['organization_matching'] = matching
    report['location_matching'] = matching['location']
    report['action_plan'] = make_action_plan(profile, supplement or {}, report['route'])
    return report

