"""可审计的四维试测规则；非心理测量常模或生产推荐引擎。"""
from __future__ import annotations

import argparse
import json
from pathlib import Path
from statistics import mean

RULE_VERSION = '0.5-scenario-1'
ROOT = Path(__file__).resolve().parent
CONFIG = json.loads((ROOT / 'questionnaire.json').read_text())
AXES = CONFIG['axes']
QUESTIONS = {q['id']: q for q in CONFIG['questions']}
CARDS = {c['code']: c for c in json.loads(
    (ROOT.parent / '16类型结果卡-v0.1.json').read_text())['records']}


def validate_answers(answers):
    if not isinstance(answers, dict):
        raise ValueError('answers 必须是以题号为键的对象。')
    unknown = set(answers) - set(QUESTIONS)
    if unknown:
        raise ValueError(f'未知题号：{sorted(unknown)}')
    for qid, value in answers.items():
        if value is not None and (type(value) is not int or not 1 <= value <= 5):
            raise ValueError(f'{qid} 必须为整数 1—5 或 null；不接受布尔值、字符串或小数。')


def score_axis(axis, answers):
    items = [q for q in QUESTIONS.values() if q.get('axis') == axis['id']]
    observations = []
    for q in items:
        x = answers.get(q['id'])
        if x is not None:
            observations.append({'question_id': q['id'], 'answer': x,
                                 'contribution': q['direction'] * (x - 3)})
    score = mean(o['contribution'] for o in observations) if observations else None
    result = {'id': axis['id'], 'label': axis['label'],
              'left': axis['left'], 'right': axis['right'],
              'answered': len(observations), 'total': len(items),
              'score': score, 'status': 'insufficient', 'letter': None,
              'evidence': observations}
    if len(observations) < CONFIG['min_answers_per_axis']:
        return result

    if axis['id'] == 'motivation':
        groups = {}
        for name, direction in [('mission', 1), ('return', -1)]:
            values = [answers[q['id']] for q in items
                      if q['direction'] == direction and answers.get(q['id']) is not None]
            groups[name] = mean(values) if len(values) >= 2 else None
        result['raw_group_means'] = groups
        if all(x is not None and x >= 4 for x in groups.values()):
            result['status'] = 'dual_high'
            return result
        if all(x is not None and x <= 2 for x in groups.values()):
            result['status'] = 'dual_low'
            return result

    if abs(score) <= CONFIG['borderline_threshold']:
        result['status'] = 'borderline'
    else:
        result['status'] = 'directional'
        result['letter'] = axis['left'] if score > 0 else axis['right']
    return result


def assess_route(axes, answers, flags):
    expectation_ids = ['Q25', 'Q26', 'Q27', 'Q28']
    evidence = [{'question_id': q, 'answer': answers.get(q)} for q in expectation_ids]
    if any(a['status'] == 'insufficient' for a in axes) or any(
            answers.get(q) is None for q in expectation_ids):
        return {'status': 'insufficient_information',
                'title': '先从一项小任务开始，找到更愿意投入的方向',
                'reason': '即使部分场景暂时难选，你仍可以先比较一次资料分析和一次伙伴沟通，把体验后的感受带回来。', 'evidence': evidence}
    if 'uniform_core_answers' in flags:
        return {'status': 'review_answers', 'title': '你的选择比较开放，先用真实任务找到偏好',
                'reason': '这次各题的选择相同。先尝试两种不同日常，再决定更想靠近哪一条职业路径。',
                'evidence': evidence}
    motivation = axes[0]
    if (motivation['letter'] == 'R'
            and all(answers[q] >= 4 for q in ['Q25', 'Q26', 'Q27'])
            and answers['Q28'] <= 2):
        return {'status': 'commercial_comparison_first',
                'title': '先去商业世界看看，不必把国际组织设为唯一主线',
                'reason': '本次回答偏重个人职业回报，期待及时反馈和较直接的激励，'
                          '对所展示的工作任务兴趣较弱。优先比较符合这些条件的岗位。',
                'evidence': motivation['evidence'] + evidence,
                'limits': '不是永久不适合的判断；商业岗位也需核对真实节奏和激励机制。'}
    return {'status': 'compare_specific_roles',
            'title': '从喜欢的日常出发，探索你的国际事务入口',
            'evidence': evidence,
            'limits': '没有触发商业优先，不等于适合国际组织或具备申请资格。'}


def experience_result(axes, exact_code):
    """始终提供可读回复；展示层不将平分或漏答伪装成确定人格。"""
    def card(code):
        return {k: CARDS[code][k] for k in ['name', 'tagline', 'portrait', 'friction', 'validation_task']}
    if '×' not in exact_code:
        return {'mode': 'primary', 'code': exact_code, 'image_code': exact_code,
                **card(exact_code), 'note': '这是本次场景选择呈现的主画像，你也可以保留另一面的偏好。'}
    directional = [a for a in axes if a['score'] is not None and a['score'] != 0]
    if not directional:
        return {'mode': 'balanced', 'code': 'OPEN', 'image_code': 'MPCS',
                'name': '平衡探索者', 'tagline': '你不急着站队，更想看清具体的人和事。',
                'portrait': '这次回答没有明显偏向某一端。你的入口可以是比较真实任务：既试一次独立分析，也试一次伙伴沟通，再看哪种过程让你更想继续。',
                'friction': '只有宏大的职位名称、却说不清每天做什么的机会，可能让你更难选择。',
                'validation_task': '选同一个公共议题：用半小时做一页资料整理，再用半小时和了解它的人聊聊。分别记录投入感和想继续的程度。',
                'note': '这是一份平衡探索建议；中立或跳过没有被偷偷换算成某种人格。'}
    scores = []
    for code in CARDS:
        fit = sum((a['score'] or 0) * (1 if code[i] == a['left'] else -1)
                  for i, a in enumerate(axes))
        scores.append((fit, code))
    scores.sort(key=lambda item: (-item[0], item[1]))
    best, primary = scores[0]
    ties = [code for score, code in scores if score == best]
    data = card(primary)
    if len(ties) > 1:
        second = ties[1]
        data.update(name=CARDS[primary]['name'] + ' × ' + CARDS[second]['name'],
                    tagline='你带着两种工作方式，遇到不同场景可以切换。',
                    portrait='一面是：' + CARDS[primary]['portrait'] + ' 另一面是：' + CARDS[second]['portrait'],
                    validation_task='分别试试：' + CARDS[primary]['validation_task'] + ' 然后，' + CARDS[second]['validation_task'])
        return {'mode': 'blend', 'code': primary + ' / ' + second,
                'image_code': primary, 'secondary_image_code': second, **data,
                'note': '这两种是与你现有回答同样接近的探索画像，没有强行替你选边。' +
                        ('仍有其他并列方向，可以先从这两种任务体验开始。' if len(ties) > 2 else '')}
    return {'mode': 'emerging', 'code': primary, 'image_code': primary, **data,
            'note': '这是目前略占上风的主画像；有些维度接近中间，请把它当作先尝试的方向。'}


def evaluate(answers):
    validate_answers(answers)
    axes = [score_axis(axis, answers) for axis in AXES]
    flags = []
    core = [answers.get(f'Q{i:02}') for i in range(1, 25)]
    if all(x is not None for x in core) and len(set(core)) == 1:
        flags.append('uniform_core_answers')
    if all(x == 3 for x in core):
        flags.append('all_core_neutral')

    code = ''.join(a['letter'] or '×' for a in axes)
    unresolved = [i for i, a in enumerate(axes) if a['letter'] is None]
    exact = not unresolved
    candidates = []
    if len(unresolved) == 1 and axes[unresolved[0]]['status'] != 'insufficient':
        pos = unresolved[0]
        for letter in [axes[pos]['left'], axes[pos]['right']]:
            candidate = code[:pos] + letter + code[pos + 1:]
            candidates.append({'code': candidate, 'name': CARDS[candidate]['name']})

    card = CARDS.get(code)
    # 不输出编辑卡中的机构线索，避免类型直接变成未经核验的个体推荐。
    portrait = ({k: card[k] for k in ['name', 'tagline', 'portrait', 'friction', 'validation_task']}
                if exact else None)
    return {'rule_version': RULE_VERSION, 'questionnaire_version': CONFIG['version'],
            'validated_psychometric_measure': False,
            'answered_total': sum(answers.get(q) is not None for q in QUESTIONS),
            'axes': axes, 'type': {'code': code,
                                 'status': 'provisional_type' if exact else 'unresolved',
                                 'portrait': portrait, 'adjacent_candidates': candidates},
            'experience': experience_result(axes, code),
            'flags': flags, 'route': assess_route(axes, answers, flags),
            'organization_matching': {'status': 'not_implemented',
                                      'reason': '仍需背景资料、具体岗位证据和可审计的匹配规则。'},
            'location_matching': {'status': 'not_implemented',
                                  'reason': '不可从类型字母直接推导总部或驻地。'}}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='读取模拟答案 JSON，打印规则试测结果。')
    parser.add_argument('answers_file', type=Path)
    args = parser.parse_args()
    try:
        answers = json.loads(args.answers_file.read_text())
        print(json.dumps(evaluate(answers), ensure_ascii=False, indent=2))
    except (ValueError, OSError) as exc:
        parser.exit(2, f'{exc}\n')

