"""Runs inside the visitor's browser. No network, storage, or server API."""
import json
from personality_v12 import CONFIG, evaluate
from action_plan import CONFIG as SUPPLEMENT_CONFIG
from general_report import generate_report
from matching import build_report

def browser_request(path, body=None):
    try:
        payload = json.loads(body) if body else None
        if path == '/api/questionnaire':
            data = CONFIG
        elif path == '/api/supplement':
            data = SUPPLEMENT_CONFIG
        elif path == '/api/score':
            data = evaluate(payload)
        elif path == '/api/report':
            data = generate_report(payload)
        elif path == '/api/career':
            if not isinstance(payload, dict) or set(payload)-{'answers','primary_path','supplement'}:
                raise ValueError('职业报告请求字段无效')
            if payload.get('primary_path') not in ('student','experienced'):
                raise ValueError('请选择主要路径')
            data = build_report(payload.get('answers',{}), {'primary_path':payload['primary_path']}, [], payload.get('supplement',{}), evaluator=evaluate)
        else:
            raise ValueError('未知请求')
        return json.dumps({'ok':True, 'data':data},ensure_ascii=False)
    except (ValueError,TypeError) as exc:
        return json.dumps({'ok':False,'data':{'error':str(exc)}},ensure_ascii=False)
